with valid_orders as (select * from orders where channel = 'web' and customer_id is null and shipping_fee is not null), agg as (select year(order_date) as order_year, channel, round((100 * sum(case when status = 'COMPLETED' then 1 else 0 end)) / count(*), 1) as pct_completed, count(distinct shipping_fee) as unique_customers from valid_orders group by year(order_date), channel) select order_year, channel, pct_completed, unique_customers from agg order by channel desc
